def cmf(nm):
    """x-bar, y-bar, z-bar at nm, linearly interpolated between 1 nm entries."""
    if nm <= START_NM:
        return list(CMF_1931_2DEG[0])
    last = START_NM + len(CMF_1931_2DEG) - 1
    if nm >= last:
        return list(CMF_1931_2DEG[-1])
    i = int(nm) - START_NM
    t = nm - int(nm)
    a, b = CMF_1931_2DEG[i], CMF_1931_2DEG[i + 1]
    return [a[k] + (b[k] - a[k]) * t for k in range(3)]
